def rank(rows, tol=1e-9):
    m = [list(map(float, r)) for r in rows]
    r = 0
    for c in range(len(m[0])):
        if r == len(m):
            break
        pivot = max(range(r, len(m)), key=lambda i: abs(m[i][c]))
        if abs(m[pivot][c]) < tol:
            continue
        m[r], m[pivot] = m[pivot], m[r]
        for i in range(len(m)):
            if i != r:
                f = m[i][c] / m[r][c]
                m[i] = [a - f * b for a, b in zip(m[i], m[r])]
        r += 1
    return r

print(rank([(1, 0, 0), (0, 1, 0), (0, 0, 1)]))          # 3: independent
print(rank([(1, 2, 3), (2, 4, 6), (0, 1, 1)]))          # 2: the second is twice the first
print(rank([(1, 2, 3), (4, 5, 6), (7, 8, 9)]))          # 2: the third is a combination of the first two
